 position: relative;
 background: linear-gradient(90deg, #f19af3, #f099b5);
 line-height: 0;
 font-size: 25px;
}

.check input[type="checkbox"],
.check label,
.check label::before,
.check label::after {
 appearance: none;
 display: inline-block;
 font-size: inherit;
 border-radius: 1em;
 border: 0;
 transition: .35s ease-in-out;
 box-sizing: border-box;
 cursor: pointer;
}

.check {
 appearance: none;
 display: inline-block;
 border-radius: 1em;
 border: 0;
 transition: .35s ease-in-out;
 box-sizing: border-box;
 cursor: pointer;
}

.check label {
 width: 2.2em;
