  box-shadow: 
                /* Neumorphic/Material shadows */
    8px 8px 16px rgba(0, 0, 0, 0.4),
    -8px -8px 16px rgba(255, 140, 0, 0.1),
    /* Subtle orange tint */ /* Skeuomorphic inset for texture */ inset 0 2px
      4px rgba(255, 255, 255, 0.1),
