  transition: all 0.4s cubic-bezier(0.4, 0, 0.2, 1); /* Material Design easing */
  transform-style: preserve-3d;
  transform: translateZ(0);
}

/* Engraved track with micro-texture */
.toggle-button::after {
  content: "";
  position: absolute;
  width: 128px;
  height: 48px;
  background: linear-gradient(
    145deg,
    rgba(255, 69, 0, 0.2),
