  transition: all 0.4s cubic-bezier(0.4, 0, 0.2, 1);
  pointer-events: none;
}

/* Textured, gem-like knob */
.toggle-button::before {
  content: "";
  position: absolute;
  width: 54px;
  height: 54px;
  background: radial-gradient(
    circle at 30% 20%,
    #ff4500,
    #ff8c00
  ); /* Orange-red gradient */
  border-radius: 20%;
  top: 3px;
  left: 3px;
  box-shadow: 
                /* Neumorphic/Material depth */
    4px 4px 8px rgba(0, 0, 0, 0.5),
    -4px -4px 8px rgba(255, 255, 255, 0.15),
    /* Skeuomorphic texture */ inset 0 -1px 3px rgba(0, 0, 0, 0.6),
    inset 0 1px 3px rgba(255, 255, 255, 0.3),
    /* Polished highlight */ 1px 1px 2px rgba(255, 255, 255, 0.2);
  transition: all 0.4s cubic-bezier(0.77, -0.4, 0.3, 1.4); /* Elastic, Material-inspired bounce */
  transform: translateZ(20px) scale(1);
  z-index: 2;
}

/* Subtle texture overlay for knob */
.toggle-button .texture {
  position: absolute;
  width: 54px;
  height: 54px;
  background: radial-gradient(circle, rgba(255, 255, 255, 0.1), transparent);
  border-radius: 50%;
  top: 3px;
  left: 3px;
