  --inset-switch: calc(var(--w-switch) * (3.75 / 100));
  --clr-on: #27ae60;
  --clr-off: #ff0000;
  --shadow-sz: calc((var(--w-switch) * (1.2 / 100)));
  width: var(--w-switch);
  height: var(--h-switch);
  display: flex;
  align-items: center;
  justify-content: center;
  background: #333;
  margin: 0px auto;
  position: relative;
  border-radius: 9999px;
  box-shadow:
