    0px var(--shadow-sz) var(--shadow-sz) rgba(255, 255, 255, 0.2),
    0 2px 5px rgba(0, 0, 0, 0.25);
}
.switch::before,
.switch::after {
  --sh-i: calc(var(--w-switch) * (0.8 / 100));
  --sh-o: calc((var(--w-switch) * (0.8 / 100)) * -1);
  position: absolute;
  z-index: 0;
  font-size: calc(var(--w-switch) * (12 / 100));
