    var(--sh-i) var(--sh-o) var(--sh-i) #1d1d1d,
    0 var(--sh-i) var(--sh-i) #111111,
    var(--sh-o) var(--sh-i) var(--sh-i) #111111,
    var(--sh-i) var(--sh-i) var(--sh-i) #000000,
    var(--sh-i) 0 var(--sh-i) #000000;
}
.switch::before {
  content: "ON";
