  visibility: hidden;
}

.slider {
  display: block;
  width: calc((var(--w-switch) / 2) - (var(--inset-switch) * 2));
  height: calc(100% - (var(--inset-switch) * 2));
  cursor: pointer;
  position: absolute;
  left: var(--inset-switch);
  z-index: 1;
