  box-shadow:
    inset 0px 1px 1px rgba(0, 0, 0),
    0px 1px 0px rgba(255, 255, 255, 0.9);
}

.switch input[type="checkbox"]:checked + .slider {
  left: calc((var(--w-switch) / 2) + var(--inset-switch));
}
.switch input[type="checkbox"]:checked + .slider::after {
