.switch {
  position: relative;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 20vmin;
  height: 10vmin;
  background: #141414;
  border-radius: 5vmin;
  overflow: hidden;
  box-shadow:
    0 0 0.1vmin 0.1vmin #000000,
    0 0 0.5vmin 0.1vmin #0b0b10 inset;
  cursor: pointer;
}

.switch input {
  display: none;
}

.thumb {
  position: absolute;
  width: 8.75vmin;
  height: 8.75vmin;
  top: 0.6vmin;
  left: calc(100% - 9.333vmin);
  border-radius: 5vmin;
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 1;
  animation: move-skull-left 0.5s ease-in-out 0.5s forwards;
}

.switch input:checked ~ .thumb {
  left: 0.6vmin;
  animation: move-skull-right 0.5s ease-in-out 0.5s forwards;
}

@keyframes move-skull-right {
  0% {
    left: 0.6vmin;
  }
  100% {
    left: calc(100% - 9.333vmin);
  }
}

@keyframes move-skull-left {
  0% {
    left: calc(100% - 9.333vmin);
  }
  100% {
    left: 0.6vmin;
  }
}

/*** Skull ***/

.thumb > * {
  position: absolute;
  filter: drop-shadow(0px 1px 1px #000);
  animation: unselected 1.5s ease-in-out 0s reverse forwards;
}

.switch input:checked ~ .thumb * {
  animation: selected 1.5s ease-in-out 0s forwards;
}

@keyframes selected {
  0%,
  50% {
    filter: drop-shadow(0px 1px 1px #000) brightness(1);
  }
  50.01%,
  100% {
    filter: drop-shadow(0px 1px 1px #000) brightness(1.875);
  }
}

@keyframes unselected {
  0%,
  50% {
    filter: drop-shadow(0px 1px 1px #000) brightness(1);
  }
  50.01%,
  100% {
    filter: drop-shadow(0px 1px 1px #000) brightness(1.875);
  }
}

.cranium {
  background: linear-gradient(180deg, #888 0 54%, #fff0 0 94%, #888 0 100%),
    radial-gradient(
      circle at 75% 69%,
      #fff0 0 0.875vmin,
      #888 calc(0.875vmin + 1px) 2.425vmin,
      #fff0 calc(2.425vmin + 1px) 100%
    ),
    radial-gradient(
      circle at 25% 69%,
      #fff0 0 0.875vmin,
      #888 calc(0.875vmin + 1px) 2.425vmin,
      #fff0 calc(2.425vmin + 1px) 100%
    );
  width: 100%;
  height: 7vmin;
  left: 0;
  top: 0;
  border-radius: 5vmin 5vmin 2.75vmin 2.75vmin;
}

.cranium:before {
  content: "";
  position: absolute;
  width: 0.625vmin;
  height: 0.625vmin;
  bottom: -0.375vmin;
  left: 3.75vmin;
  background: #888;
  border-radius: 100%;
