}

.cranium:after {
  content: "";
  position: absolute;
  width: 2.625vmin;
  height: 0.75vmin;
  bottom: -0.475vmin;
  left: 3vmin;
  background: radial-gradient(
      circle at 90% 10%,
      #888 0 0.5vmin,
      #fff0 calc(0.5vmin + 1px) 100%
    ),
    radial-gradient(
      circle at 10% 10%,
      #888 0 0.5vmin,
      #fff0 calc(0.5vmin + 1px) 100%
    );
  border-radius: 0.5vmin;
}

.mouth {
  border: 0.425vmin solid #fff0;
  border-bottom-color: #888;
  width: 5.875vmin;
  left: 1.425vmin;
  height: 3vmin;
  top: 5.625vmin;
  background: radial-gradient(
      circle at 35% 98%,
      #888 0 0.325vmin,
      #fff0 calc(0.325vmin + 1px) 100%
    ),
    radial-gradient(
      circle at 45% 100%,
      #888 0 0.325vmin,
      #fff0 calc(0.325vmin + 1px) 100%
    ),
    radial-gradient(
      circle at 55% 100%,
      #888 0 0.325vmin,
      #fff0 calc(0.325vmin + 1px) 100%
    ),
    radial-gradient(
      circle at 65% 98%,
      #888 0 0.325vmin,
      #fff0 calc(0.325vmin + 1px) 100%
    );
  background-repeat: no-repeat;
  border-radius: 100%;
}

.mouth:before,
.mouth:after {
  content: "";
  position: absolute;
  border-radius: 100%;
  background: #888;
  width: 0.35vmin;
  height: 0.35vmin;
  left: 0.2vmin;
  bottom: 0.125vmin;
}

.mouth:after {
