}

/*** Arm ***/

@keyframes check-on {
  0% {
    right: -65%;
  }
  25%,
  33% {
    right: 0%;
  }
  66%,
  80% {
    right: -50%;
  }
  100% {
    right: -65%;
  }
}

@keyframes check-off {
  0% {
    right: -65%;
  }
  25%,
  33% {
    right: 0%;
  }
  66%,
  80% {
    right: -50%;
  }
  100% {
    right: -65%;
  }
}

.arm-wrapper {
  position: absolute;
  width: 100%;
  height: 100%;
  border-radius: 5vmin;
  overflow: hidden;
  right: -65%;
  animation: check-off 1.5s ease-in-out 0s reverse forwards;
}

.switch input:checked ~ .arm-wrapper {
  animation: check-on 1.5s ease-in-out 0s forwards;
}

.arm {
  position: absolute;
  width: 8vmin;
  height: 2.5vmin;
  right: 2%;
  top: calc(50% - 1.25vmin);
  border-radius: 0.125vmin;
}

.bone {
  background: #fff;
  width: 4vmin;
  height: 1vmin;
  position: absolute;
  transform: rotate(0deg);
  top: 0.75vmin;
  right: -2vmin;
}

.bone:before,
.bone:after,
.big:before,
.big:after {
  content: "";
  background: #fff;
  width: 0.75vmin;
  height: 0.75vmin;
  position: absolute;
  left: -0.25vmin;
  top: -0.25vmin;
  border-radius: 100%;
  box-shadow: 4vmin 0 0 0 #fff;
}

.bone:after {
  top: calc(100% - 0.5vmin);
}

.arm > .bone + .bone {
  top: 0.75vmin;
  left: 0.25vmin;
  height: 0.425vmin;
  width: 5.25vmin;
  box-shadow: 0 0.575vmin 0 0 #fff;
}
.arm > .bone + .bone:before,
.arm > .bone + .bone:after {
  box-shadow: 5.075vmin 0 0 0 #fff;
}

.arm > .bone + .bone:after {
  top: 100%;
}

