/* The switch - the box around the slider */
.switch {
  --INITIAL-SWITCH-TRACK-COLOR: #fffbeb;
  --INITIAL-THUMB-COLOR: #ff5722;
  --OVERALL-TRANSITION-DURATION: 500ms; /* Overall transition speed */
  font-size: 17px;
  position: relative;
  display: inline-block;
  width: 3.75em;
  height: 2em;
}

/* Hide default HTML checkbox */
.switch input {
  opacity: 0;
  width: 0;
  height: 0;
}

/* The slider */
.slider {
  position: absolute;
  cursor: pointer;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background-color: var(--INITIAL-SWITCH-TRACK-COLOR);
  transition: var(--OVERALL-TRANSITION-DURATION);
  border-radius: 30px;
  overflow: hidden;
}

/* Thumb */
.slider:before {
  position: absolute;
  content: "";
  height: 100%;
  aspect-ratio: 1;
  border-radius: 20px;
  left: 0;
  bottom: 0;
  background-color: var(--INITIAL-THUMB-COLOR);
  transition: var(--OVERALL-TRANSITION-DURATION);
}

.switch input:checked + .slider {
  background-color: var(--INITIAL-THUMB-COLOR);
}

/* Actions to be performed when the switch is TOGGLED ON */
.switch input:checked + .slider::before {
  transform-origin: left;
  background-color: var(--INITIAL-SWITCH-TRACK-COLOR);
  animation: wobble var(--OVERALL-TRANSITION-DURATION)
    cubic-bezier(0.075, 0.82, 0.165, 1);
  transform: scale(1, 1) translateX(2rem);
}

/* Actions to be performed when the switch is TOGGLED OFF */
.switch input:not(:checked) + .slider::before {
  transform-origin: right;
  animation: reverse-wobble var(--OVERALL-TRANSITION-DURATION)
    cubic-bezier(0.075, 0.82, 0.165, 1);
}

@keyframes wobble {
  0% {
    transform: scale(1, 1);
  }
  50% {
    transform: scale(3, 1);
  }
  100% {
    transform: scale(1, 1) translateX(2rem);
  }
}

@keyframes reverse-wobble {
  0% {
    transform: scale(1, 1) translateX(2rem);
  }
  50% {
    transform: scale(3, 1);
  }
  100% {
    transform: scale(1, 1) translateX(0);
  }
}

/* To hide the checkbox */
#checkboxInput {
  display: none;
}

.toggleSwitch {
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
  width: 50px;
  height: 17px;
  background-color: rgb(82, 82, 82);
  border-radius: 20px;
  cursor: pointer;
  transition-duration: .2s;
}

.toggleSwitch::after {
  content: "";
  position: absolute;
  height: 22px;
  width: 22px;
  left: 0px;
  background-color: rgb(41, 41, 41);
  border-radius: 50%;
  transition-duration: .2s;
  border: 2px solid rgb(82, 82, 82);
}

#checkboxInput:checked+.toggleSwitch::after {
  transform: translateX(100%);
  transition-duration: .2s;
  border: 2px solid rgb(165, 255, 105);
}
/* Switch background change */
#checkboxInput:checked+.toggleSwitch {
  background-color: rgb(165, 255, 105);
  transition-duration: .2s;
}

.toggle-container {
  perspective: 1000px;
}

.toggle-container input {
  display: none; /* Hide default checkbox */
}

.toggle-button {
  position: relative;
  width: 100px;
  height: 50px;
  background: linear-gradient(145deg, #e6e6e6, #ffffff);
  border-radius: 25px;
  box-shadow: 
                /* Neumorphic outer shadows */
    8px 8px 16px rgba(0, 0, 0, 0.1),
    -8px -8px 16px rgba(255, 255, 255, 0.7),
    /* Skeuomorphic inset for depth */ inset 0 2px 4px rgba(255, 255, 255, 0.8),
    inset 0 -2px 4px rgba(0, 0, 0, 0.15);
  cursor: pointer;
  transition: all 0.4s cubic-bezier(0.68, -0.55, 0.265, 1.55); /* Elastic bounce */
}

.toggle-button::before {
  content: "";
  position: absolute;
  width: 46px;
  height: 46px;
  background: linear-gradient(145deg, #ff6b6b, #ff3b3b);
  border-radius: 50%;
  top: 2px;
  left: 2px;
  box-shadow: 
                /* Neumorphic knob shadow */
    4px 4px 8px rgba(0, 0, 0, 0.2),
    -4px -4px 8px rgba(255, 255, 255, 0.9),
    /* Skeuomorphic depth */ inset 0 -1px 2px rgba(0, 0, 0, 0.3);
  transition: all 0.4s cubic-bezier(0.68, -0.55, 0.265, 1.55);
  transform: translateZ(12px); /* 3D pop-out effect */
}

.toggle-button::after {
  content: "";
  position: absolute;
  width: 92px;
  height: 42px;
  background: linear-gradient(
    145deg,
    rgba(255, 255, 255, 0.2),
    rgba(0, 0, 0, 0.1)
  );
  border-radius: 21px;
  top: 4px;
  left: 4px;
  transition: all 0.4s ease-in-out;
  pointer-events: none; /* Prevent interaction with pseudo-element */
}

.toggle-container input:checked ~ .toggle-button {
  background: linear-gradient(145deg, #c3e6cb, #d4f4dd);
  box-shadow:
    8px 8px 16px rgba(0, 0, 0, 0.1),
    -8px -8px 16px rgba(255, 255, 255, 0.7),
    inset 0 2px 4px rgba(255, 255, 255, 0.8),
    inset 0 -2px 4px rgba(0, 0, 0, 0.15);
}

.toggle-container input:checked ~ .toggle-button::before {
  left: 52px;
  background: linear-gradient(145deg, #2ecc71, #27ae60);
  transform: translateZ(12px) rotate(360deg); /* Spin animation */
}

.toggle-container input:checked ~ .toggle-button::after {
  background: linear-gradient(
    145deg,
    rgba(255, 255, 255, 0.3),
    rgba(0, 0, 0, 0.05)
  );
}

.toggle-button:active::before {
  transform: translateZ(8px); /* Pressed effect */
  box-shadow:
    2px 2px 4px rgba(0, 0, 0, 0.2),
    -2px -2px 4px rgba(255, 255, 255, 0.9);
}

/* Hover effect for extra interactivity */
.toggle-button:hover {
  box-shadow:
    10px 10px 20px rgba(0, 0, 0, 0.15),
    -10px -10px 20px rgba(255, 255, 255, 0.8);
}

/* Subtle animation for toggle track */
@keyframes track-glow {
  0% {
    box-shadow: inset 0 0 5px rgba(0, 0, 0, 0.2);
  }
  50% {
    box-shadow: inset 0 0 10px rgba(0, 0, 0, 0.3);
  }
  100% {
    box-shadow: inset 0 0 5px rgba(0, 0, 0, 0.2);
  }
}

.toggle-container input:checked ~ .toggle-button::after {
  animation: track-glow 1.5s infinite;
}

