  display: flex;
  align-items: center;
  justify-content: center;
  transition: left 0.2s cubic-bezier(0.34, 1.56, 0.64, 1);
}

/* Thumb slides right when checked */
.retro-toggle input:checked ~ .retro-track .retro-thumb {
  left: calc(100% - 2rem - 4px);
}

/* ── Power SVG icon ── */
.power-icon {
  width: 16px;
  height: 16px;
  stroke-width: 2;
  fill: none;
  stroke-linecap: round;
  stroke-linejoin: round;
  stroke: #dc2626; /* red = OFF */
